// Requests/ClockInRequest.cs
public sealed record ClockInRequest(int EmployeeId, DateTime ClockInTime);

// Responses/ClockEntryResponse.cs
public sealed record ClockEntryResponse(int EmployeeId, DateTime ClockInTime);

// Controllers/ClockEntriesController.cs
using Microsoft.AspNetCore.Mvc;

[ApiController]
[Route("clock-entries")]
public sealed class ClockEntriesController : ControllerBase
{
    private readonly AsyncClockEntryService _service;

    public ClockEntriesController(AsyncClockEntryService service)
    {
        _service = service;
    }

    [HttpPost("clock-in")]
    public async Task<ActionResult<ClockEntryResponse>> ClockInAsync(ClockInRequest request, CancellationToken cancellationToken)
    {
        if (request.EmployeeId <= 0)
        {
            return BadRequest("EmployeeId must be positive.");
        }

        bool accepted = await _service.TryClockInAsync(request.EmployeeId, request.ClockInTime, cancellationToken);
        if (!accepted)
        {
            return Conflict("The employee already has an open clock entry.");
        }

        ClockEntryResponse response = new ClockEntryResponse(request.EmployeeId, request.ClockInTime);
        string location = $"/clock-entries/{request.EmployeeId}/open";
        return Created(location, response);
    }
}

// Program.cs
using Microsoft.EntityFrameworkCore;

WebApplicationBuilder builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
Action<DbContextOptionsBuilder> configureDatabase = (DbContextOptionsBuilder optionsBuilder) =>
{
    optionsBuilder.UseSqlite("Data Source=timeclock.db");
};
builder.Services.AddDbContext<TimeClockDbContext>(configureDatabase);
builder.Services.AddScoped<IAsyncClockEntryRepository, EfClockEntryRepository>();
builder.Services.AddScoped<AsyncClockEntryService>();
WebApplication app = builder.Build();
using (IServiceScope scope = app.Services.CreateScope())
{
    TimeClockDbContext dbContext = scope.ServiceProvider.GetRequiredService<TimeClockDbContext>();
    await dbContext.Database.EnsureCreatedAsync();
}
app.MapControllers();
app.Run();
